  "/ 随笔": "/ Word",
  "// AI 上线前准入评审表\n// 评测维度: [功能准确性 / 越狱鲁棒性 / 延迟响应 / 成本预算 / 降级策略]\n// 准入基准: 核心场景 Recall >= 99%, 平均延迟 <= 3.5s": "/ AI Access Review Form\n// Assessment of dimensions: [Function accuracy / Prison breakout robustness / Delay response / Cost budget / Degrade strategy]\n/ Access benchmarks: Core scenario Recall > = 99%, average delay < = 3.5s",
  "0-10 分制存在严重的分数漂移问题（今天 7 分明天 8 分），评测人员无法对中间分数达成共识，且无法自动化回归。": "There is a serious problem with the fractional drift of the 0-10 fraction system (7 today, 8 tomorrow), and the evaluators are unable to agree on the intermediate score and to automate the return.",
  "1. 意图覆盖 2. 事实真实 3. 边界拒绝 4. 逻辑连贯 5. 格式完备 6. 引导得当 7. 语气同理": "1. Intent to cover 2. Truth 3. Boundary rejection 4. Logical consistency 5. Format is adequate 6. Rice",
  "1. 抛弃循环时序，利用矩阵乘法实现 GPU 算力利用率的最大化。": "1. Discard the cycle time series and use the matrix multiplication to maximize the utilization of the GPU algorithm.",
  "1. 显式推理轨迹 (Thought) 能大幅降低工具调用的盲目性与误触发。": "1. The Visible Logic Track (Thought) can significantly reduce blindness and trigger error in the use of tools.",
  "1. 检索与生成分离，解耦了静态模型推理能力与动态业务知识库。": "1. Separating search and generation decomposes static model reasoning and dynamic business knowledge base.",
  "1. 自然语言原则可以作为强化学习的高效奖励信号。": "1. The principle of natural languages can serve as an efficient reward for enhanced learning.",
  "15 章 · 系列学习": "• Study series",
  "2. Multi-Head 机制提供了多维度的语义注意力聚合空间。": "The Multi-head mechanism provides a multidimensional semantic concentration space.",
  "2. 环境观察 (Observation) 充当了模型对抗自身幻觉的物理世界锚点。": "2. Environment Watch serves as the physical world anchor for modelling against its own hallucinations.",
  "2. 相比微调，RAG 具有零训练成本、实时更新与强可溯源性的优势。": "2. Compared to fine-tuning, RAG has the advantage of zero training costs, real-time renewal and robust traceability.",
  "2. 自我批评与迭代重写 (Critique & Revise) 能显著提升输出质量。": "Self-critical and iterative rewrite (Critique & Revise) can significantly improve output quality.",
  "2026.09 — 至今": "2026.09 — To date",
  "2026.09.12 23:06 的状态文档记录请求成功返回，审核一次，三张下载图片均为 1080×1080；本次网站整理未独立重跑。": "2026.09.12 The status file request was successfully returned and reviewed once, with three downloads of 1080 x 1080; no independent rerun was organized on this site.",
  "3 天 → 12 分钟": "3 days 12 minutes",
  "3-Shot（含 1 个正例、1 个边缘 Case、1 个负例反思）配合理由先行 CoT，将打分方差从 0.84 骤降至 0.09，一致性与人工专家吻合度达到 93.8%。": "3-Shot (comprising 1 positive, 1 marginal Case, 1 negative reflection) goes first, and COT reduces the scoring margin from 0.84 to 0.09, and aligns it with manual experts to 93.8 per cent.",
  "3. Agent 的稳定性很大程度上取决于每一步 Observation 的结构化清晰度。": "3. The stability of Agent depends to a large extent on the structural clarity of each step of Operation.",
  "3. RAG 系统的主要瓶颈在检索召回精度与上下文拼接策略。": "3. The main bottlenecks in the RAG system are the retrieval of accuracy and context fusion strategies.",
  "3. 注意力矩阵的平方复杂度 O(N^2) 决定了当前长上下文的硬件与成本边界。": "3. The square complexity of the attention matrix O(N^2) determines the current long context hardware-cost boundary.",
  "3. 规则透明度使得模型的价值对齐具备可解释性与可调整性。": "3. Transparency in rules allows for interpretability and adaptability of the value matching of models.",
  "30 分钟 → 30 秒": "30 min, 30 seconds.",
  "320px 宽度不横向滚动": "320px width does not scroll horizontally",
  "404 表示服务器未找到与请求地址匹配的资源。": "404 indicates that the server did not find resources matching the address requested.",
