  "AI 为什么会一本正经地瞎编？": "AI, why are you making this up?",
  "AI 交互应该围绕 Artifact（产物）展开，AI 充当后台编译器或行内 copilot，而非永远让用户面对一个空白聊天框。": "AI should be interactive around Artifact (product), and AI acts as a back-stage compiler or line copilot, rather than always subjecting users to a blank chat box.",
  "AI 产品从 0 到 1": "AI products from 0 to 1",
  "AI 产品从 0 到 1：从问题到持续迭代": "AI products from 0 to 1: from problem to duration Sub.",
  "AI 产品经理不需要推导矩阵公式，但必须理解：模型对上下文的“注意力”是有选择性的，关键指令放在最前或最后更容易被捕捉（Lost in the Middle 现象根源）。": "The AI product manager does not need to extrapolate the matrix formula, but it must be understood that the model is selective in terms of the context of “focus” and that key directives are at the forefront or at the end more likely to be captured (the root causes of the Lost in the Middle phenomenon).",
  "AI 产品需求与意图边界分析 PRD 模板": "AI Product Demand and Intention Border Analysis PRD Template",
  "AI 分类与去背（实际调用仍待验收）": "AI Classification and Backback (actual call still pending)",
