  "AI 基础": "AI Foundation",
  "AI 实际调用、iOS / Android 手势、相册授权、保存顺序与真实微信聊天效果仍待完整验收。": "AI actual calls, iOS / Android gestures, album authorizations, save sequences and authentic tweets are still awaiting full acceptance.",
  "AI 工具": "AI Tools",
