  "AI 应用基础": "AI Application Basics",
  "AI 应用把模型能力与输入、工具、界面和验证流程组合起来完成任务。": "AI uses a combination of model capabilities with input, tools, interfaces and validation processes to accomplish the task.",
  "AI 把代码改坏了，怎么放心地回退？": "AI, change the code. How can you turn back?",
  "AI 提炼结果默认“仅保存”，生成公开草稿需经人工把关，避免 AI 制造无价值垃圾内容。": "AI refining results are by default \"saved only\" and the production of public drafts requires manual clearance to avoid AI making worthless waste content.",
  "AI 摘要功能的 PRD 要写输入限制、失败处理和效果标准。": "The PRD for the AI summary function is to write input limits, failure processing and effect criteria.",
  "AI 结果具有不确定性，界面需要帮助用户检查依据、编辑内容和控制执行，而不是只展示一段看似确定的答案。": "AI results are uncertain and the interface needs to help users check the basis, edit content and control execution, rather than displaying only a seemingly definitive answer.",
  "AI 说某配置已经生效，最可靠的下一步是？": "AI says a configuration is in effect, and what's the most reliable next?",
  "AI 辅助梳理方案、生成设计参考、实现页面、整理代码证据与运行测试；项目方向和体验反馈由本人提出。": "AI Auxiliary combo programmes, generation of design references, page realization, organization of code evidence and running tests; project direction and experience feedback from the person.",
  "AI 适用性需要与规则、搜索、数据库和人工方案比较。选择依据是任务价值、可接受误差和整体成本。": "AI Applicability requires comparison with rules, searches, databases and manual programmes. Selection is based on mission value, acceptable error and overall cost.",
  "AI、产品实践与个人知识系统。": "AI, product practices and personal knowledge systems.",
  "AI工程化": "AI Engineering",
  "API 代理 / 中转站": "API Proxy",
  "API 契约": "API Contract",
  "API 契约定义一个请求的地址、方法、参数、身份要求、成功结果和错误格式，是服务之间可验证的共同约定。": "The API contract defines the address, method, parameters, identity requirements, successful outcome and incorrect format of a request as a verifiable mutual agreement between services.",
  "API 密钥": "API Key",
  "API 密钥最不应该放在哪里？": "Where should I put the API key?",
  "API 把调用方与内部实现隔开，前端只需遵守约定，不必知道数据具体存在哪张表。": "API separates the caller from the internal realization, and the front end has to comply with the agreement without knowing which table the data actually exist.",
  "API 是一个系统向其他程序公开的可调用能力，Web API 通常通过 HTTP 地址接收参数并返回结构化结果。": "API is a system that is publicly available to other programs, and Web API usually receives parameters through HTTP addresses and returns to structured results.",
  "API 是什么？": "API, what is it?",
