  "以求职者筛选岗位为练习：观察他怎样阅读 JD、记录要求和决定是否申请。不要预设一定需要自动打分。": "The job-seeker screening position is used as a practice: to observe how he reads JD, record requirements and decides whether to apply. Do not preset that automatic scoring is necessary.",
