  "传统个人博客或知识库维护成本过高，容易陷入“为了写文章而写文章”的脱节状态；需要让日常做项目的过程自然沉淀为高质量知识资产。": "Traditional personal blogs or knowledge banks are too costly to maintain, and are prone to a disconnect between “writing for writing” articles; the process of doing daily projects needs to naturally sink into high-quality knowledge assets.",
  "传统强化学习 (RLHF) 依赖大量人工标注员对有害内容打标，成本极其高昂，且标注员容易产生心理疲劳或引入个人主观偏见。": "Traditional Enhanced Learning (RLHF) relies on a large number of manual labelers to mark harmful content, which is extremely expensive and prone to psychological fatigue or the introduction of individual subjective bias.",
  "低保真原型": "Prototype of low security",
  "作为刚入门的开发者，我想收藏术语，以便下次快速回到正在理解的概念。": "As the first developer, I would like to collect terminology so that next time I quickly return to the concept that is being understood.",
  "你喜欢我们的学习地图吗？": "Do you like our study map?",
  "你是一个资深全栈架构师与技术选型顾问。请阅读以下 GitHub 开源项目信息，输出结构化分析报告：\n\n【输出结构】\n1. 一句话定位：用最通俗的技术语言说明它解决什么问题\n2. 核心架构原理：它是怎么实现的？（关键组件与数据流）\n3. 最大技术优势：相比同类方案的核心亮点（最多 3 点）\n4. 潜在缺陷与风险：性能瓶颈、依赖沉重、学习曲线或维护风险\n5. 适用业务场景：什么情况下应该用它？什么情况下坚决不要用？\n6. 我的选型建议：[强烈推荐 / 审慎评估 / 不推荐] 及一句话理由": "You're a senior in-house architect and technical consultant. Read the following GitHub open source project information, output structured analysis:\n\n[output structure]\n1. Positioning in a single sentence: an indication of what it addresses in the most common technical language\n2. Core architecture: How has it been achieved? (Key Component and Data Flow)\n3. Maximum technical advantage: Core highlights compared to similar programmes (up to 3 points)\n4. Potential deficiencies and risks: performance bottlenecks, heavy reliance, learning curves or maintenance risks\n5. Applicable business scenario: in what circumstances should it be used? What circumstances do you insist not to use?\n6. My selection proposal: [Recommended strongly]/Cautionary assessment]/No recommendation] and the rationale for one sentence",
  "你是谁": "Who are you?",
  "你给出的 Prompt 和 Schema 越具确定性，AI 的产出质量上限就越高。": "The more certainty you give Prompt and Schema, the higher the output quality cap for AI.",
  "你能做什么": "What can you do?",
  "使用 --color-action 表示主要操作色，夜航模式只需重新定义该语义变量。": "Use --color-action for the main operating colour, and the night mode needs only to redefine the semantic variable.",
  "使用 1-5 星打分，导致不同测试轮次间出现打分漂移。": "Ratings are used for 1-5 stars, resulting in a scoring drift between different test cycles.",
  "使用 CSS 变量统一操作色，并在窄屏断点把三列课程卡改成单列。": "Harmonizes the operating colours with CSS variables and changes the three series of course cards to a single column at the narrow screen breakpoint.",
  "使用 border-box 时把边框和内边距计算进声明宽度。": "Calculates the border and inner margin for the width of the statement when using the border-box.",
  "使用 sync-push.bat / sync-pull.bat 手动同步，或通过 sync-watch.bat 监听变更。": "Use sync-push.bat / sync-pull.bat to synchronize manually, or listen to changes via sync-watch.bat.",
  "使用“尽量”“适当”等模糊词": "Use vague words such as “as far as possible”",
  "使用一组明确编写的原则规范（宪法 Constitution）引导模型对自身的输出进行自我反思、批判和修改，用 AI 反馈替代高昂的人工标注 (RLHF)。": "Using a clearly prepared set of norms of principle (Constitution) to guide models for self-reflection, criticalisation and modification of their output, and replacing high manual labelling (RLHF) with AI feedback.",
  "使用参数化查询": "Use parameterized query",
  "使用方法": "Use method",
  "使用示例": "Use Example",
  "使用结构化输出，要求模型先从对话中抽取证据片段，再陈述判断理由，最后输出 passed: true/false。": "Using a structured output, the model is required to extract a piece of evidence from the dialogue before presenting a reason for judgement.",
  "使用给定情境—操作—结果描述行为": "Use given context-operate-result to describe behavior",
  "使用统一间距与颜色规则，避免页面堆出互相冲突的任意值。": "Use uniform spacing and colour rules to avoid any conflicting values stacking pages.",
  "使用脆弱的层级选择器": "Use weak hierarchy selector",
  "例如，在注册页，输入框、提交按钮和“正在提交 / 注册成功 / 出错了”的提示属于前端；账号是否真正创建成功，要由后端处理后返回结果。": "For example, on the registration page, the input box, the submission button and the hint \" is submitting / registration success / error \" are at the front end; whether the account has actually been created successfully is to be returned after a backend process.",
  "例子与观察": "Examples and observations",
  "依据你提供的 AI 产品从 0→1 学习资料整理，正文为站内编写。": "Based on the AI product that you have provided, it is organized from 0:01 learning materials, written for the site in the body.",
