  "做事情才是主干，整理知识是流水线自动化辅助；好系统不是让用户做更多输入，而是用确定性契约帮用户把无序材料编译成高信息密度的结构。": "Doing things is the main thing, and organizing knowledge is aided by the automation of flow lines; a good system does not allow users to enter more, but rather helps users to compile unordered materials into high-information-density structures using firm compacts.",
