  "圆角的气质": "Corner Feel",
  "在 100 组具有争议的线上真实对话轨迹上，对比 0-Shot、1-Shot、3-Shot 与思维链 CoT 对模型打分方差的影响。": "On the track of real dialogue on a controversial 100-assembly line, contrasting 0-Shot, 1-Shot, 3-Shot and the thought chain COT have the effect of scoring differences in models.",
  "在 200 次长文本抽取任务中，对比纯自然语言指令、Markdown 代码块标记、JSON Schema 约束与理由先行四种方案的解析失败率。": "In a 200-long text extraction task, compare the failure rate of the pure natural language command, the Markdown code block marker, the JSON Schema constraint and the rationale for the first four scenarios.",
  "在 360px 宽度下无横向滚动且主导航可操作": "No horizontal scroll at 360px width and main navigable",
  "在 AI 图片小程序与七维评测项目中全面使用此 PRD 规范，使前后端与 Prompt 调优团队的对接返工率降低 60%。": "The full use of this PRD standard in the AI Photo Applet and the 7-D assessment project reduces the back-to-back rate of the front-end and Prompt-modified team by 60%.",
  "在 AI 辅助编程时代，工程师的核心竞争力究竟转移到了哪里？": "Where did the core competitiveness of engineers shift in the AI Auxiliary Programming Age?",
  "在 Agent 质量评测流水线中，为什么不能用单一全能 Prompt 搞定所有维度的打分？": "In the Agent Quality Assessment Flow Line, why can't a single all-power Prompt score all dimensions?",
  "在 Elements 面板确认真实节点": "Confirm real nodes on the Elements Panel",
  "在 JavaScript 基础上增加静态类型系统的语言。": "Add static type system language to JavaScript.",
  "在 LLM Prompt 中要求模型计算数字总和或比对很长的固定字符串（应由规则引擎完成）。": "In LLM Prompt the model is required to calculate the sum of the numbers or a long fixed string (which should be done by the rule engine).",
  "在 Personal Knowledge Lab 选型初期，使用该 Prompt 快速对比了 4 个静态站与 Markdown 解析引擎，最终确定轻量 Vanilla 方案。": "In the early stages of the personal Knowledge Lab selection, the Prompt quickly compared the 4 static stations with the Markdown decomposition engine to finalize the light Vanilla programme.",
  "在 TLS 保护下传输 HTTP 数据，提供传输加密及服务身份验证。": "Transfer HTTP data under TLS protection, providing transmission encryption and service authentication.",
  "在 feature/term-atlas 开发词库扩展，验证完成后通过合并请求进入主线。": "Enter the main line by merging the request after validation has been completed in the development of the vocabulary extension for feature/term-atlas.",
  "在一个系统中处理或结合文本、图像、音频等多种信息形式的能力。": "The ability to process or combine multiple forms of information such as text, images, audio in a system.",
  "在七维能力自动评测系统中，团队将原来长达 1500 字的混合打分 Prompt 拆分为 1 个规则引擎脚本 + 7 个原子 Judge Prompt，评测一致性从 71% 跃升至 94.2%，运行耗时缩短 60%。": "In the seven-dimensional capacity automatic assessment system, the team splits the original 1,500-word hybrid Prompt into one rule engine script + 7 atoms Judge Prompt, leaping from 71 per cent to 94.2 per cent for consistency assessment and a 60 per cent reduction in running time.",
  "在七维能力评测系统中，如果把“是否包含订单号”、“是否跳转状态码 200”和“态度是否真诚”混在一个 Prompt 里，LLM 会经常对订单号缺失视而不见，而给出 85 分的矛盾分数；拆分为“代码规则过滤层 + 语义二元断言层”后，确定性错误拦截率直接达到 100%，整体一致性达到 94.2%。": "In a seven-dimensional capability assessment system, LLM often turns a blind eye to the order number when it is mixed with the order number, the jump state code 200 and the attitude sincerity, and gives a contradictory score of 85 points; after breaking down into the \"code rule filter + semantic binary assertion layer\" the sexual error interception rate is directly 100 per cent and the overall consistency is 94.2 per cent.",
  "在七维能力评测系统的 3 次版本迭代中，严格依据此 Checklist 拦截了 2 起潜在 Prompt 越狱漏洞。": "On the basis of this three-ever version of the seven-dimensional competency assessment system, Checklist stopped two potential Prompt escapes.",
  "在不同屏幕验证规则。": "Checking rules on different screens.",
  "在不同资源组间使用淡分割线，不为每一行制造强边框。": "A light dividing line is used among different resource groups and no strong border is created for each line.",
  "在不重新发布全部代码的情况下控制功能是否开启的开关。": "Controls whether the switch is open without reissuing all codes.",
  "在严苛生产环境中，不同类型的错误代价完全不同（漏拦截一次敏感越权指令的代价是灾难性的，而误拦截普通提问只是稍损体验）。必须针对关键风险维度分别计算 Recall（查全率）并设置硬性拦截阈值。": "In a demanding production environment, the costs of different types of errors are quite different (the cost of missing a sensitive ultra vires instruction is catastrophic, while the error of intercepting an ordinary question is only a slight loss). Recall must be calculated separately for the critical risk dimensions and rigid interdiction thresholds must be set.",
  "在任何包含大模型调用、Agent 工作流或生成式 AI 功能发布到正式生产环境前。": "Releases any AI that contains a large model call, Agent workflow or generation function to the official production environment.",
  "在任务目标下，由模型参与决定步骤与工具使用的执行系统。": "Under mission objectives, the model is involved in determining the implementation system for the steps and tools to be used.",
  "在体验退化前暴露资源增长": "Exposure to resource growth before experiencing degradation",
  "在写代码前访谈目标用户，验证任务是否高频且值得改善。": "Interview the target user before writing the code to verify that the mission is high and deserves improvement.",
  "在前端暴露私密 API Key": "Exposure of private API Key to frontend",
  "在受限目录运行实验，明确网络和文件写入是否可用。": "Run experiments in restricted directories to specify whether network and file writing is available.",
  "在另一个工作树修复问题，避免打断当前分支的未提交改动。": "In another working tree restoration issue, the unsubmitted changes to the current branch were avoided.",
  "在合入主线前展示变化、讨论风险并运行检查。": "Display changes, discuss risks and run checks before joining the main line.",
