  "在小数据集上，带重叠窗口的滑动切分召回率比硬换行切分提高 32%，能有效解决关键上下文被切断的问题。": "On the small data set, the rate of retrieving the slide splits with overlapping windows increased by 32 per cent over the hard-line cut points, effectively addressing the issue of cutting critical contexts.",
