  "在提交前后检查输入，并告诉用户如何修正。": "Check the input before and after submission and tell the user how to fix it.",
  "在文章段落之间加外边距，而不扩大文字背景区域。": "Add a margin between the paragraphs of the article without expanding the text background area.",
  "在日志中记录密码": "Record password in log",
