  "在极端长输入与空输入下测试过鲁棒性": "Tests of greatness under extreme long and empty input",
  "在构建本 Personal Knowledge Lab 时，定义清晰的 6 字段数据契约与单向数据流，AI 可以在 30 秒内准确补全完整的组件代码；若缺乏清晰契约，AI 生成的代码将迅速失控并互相冲突。": "In the construction of this personal Knowledge Lab, a clearly defined six-field data contract and one-way data stream can be completed accurately by AI in 30 seconds; in the absence of a clear contract, the codes generated by AI quickly lose control and conflict with each other.",
  "在检查通过后长期保存这次修改。": "This change is kept permanently after the inspection.",
  "在此之前，RNN/LSTM 必须按时间步序列串行处理文本，无法利用 GPU 大规模并行加速，且在处理超过百字的长文本时极易发生梯度消失与遗忘。": "Prior to this, RNN/LSTM had to process text in a time-sequencing sequence, unable to use GPU for large-scale parallel acceleration, and highly susceptible to the disappearance and oblivion of gradients when dealing with long text exceeding 100 words.",
  "在没有相关代码变化时仍时过时败的测试。": "Tests that are out of date when there is no relevant code change.",
  "在流水线最前端执行规则断言。若规则失败，直接输出错误码并终止后续 LLM 推理，节省成本。": "The enforcement of the rules at the front end of the line. If the rule fails, directly output the wrong code and terminate subsequent LLM reasoning, saving costs.",
  "在流程中设置人工判断、确认或修正的环节。": "Sets a manual judgement, confirmation or correction link in the process.",
  "在测试中替代真实依赖的对象，例如桩、模拟或假实现。": "Substitution of real dependent objects in tests, such as stakes, simulations or false realizations.",
  "在浏览器之外处理可信规则、请求和持久化数据。": "Handle credible rules, requests and persistent data outside the browser.",
  "在深浅背景中使用可辨认的品牌版本。": "Use an identifiable brand version in the underlying context.",
  "在滚动达到阈值后保持在容器边界内指定位置的定位方式。": "Maintains the location of the assigned position within the boundary of the packaging after the rolling threshold has been reached.",
  "在特定生命周期事件发生时执行扩展逻辑的机制。": "Mechanisms to implement the expansive logic in the event of an event occurring during a given life cycle.",
  "在生产者与消费者之间存放消息，解耦发送和处理速度的机制。": "(c) Mechanisms for depositing information between producers and consumers, decoupling transmission and processing speed.",
  "在目标视口运行页面并检查截图与交互": "Run page on target visual and check screenshots and interactions",
  "在相应堆叠上下文内控制元素前后顺序的属性。": "Controls the properties of the order of the elements in the corresponding stacking context.",
  "在真实环境检查配置和行为": "Check configuration and behaviour in real environment",
  "在空间有限时截短文本，并提示内容尚未完整显示。": "Short text when space is limited and hints are not fully displayed.",
  "在纯浏览器端基于 TF-IDF 与简易余弦相似度实现的完全离线文档分块、向量化与上下文动态注入 Demo。": "A complete offline document segment based on the TF-IDF similarity to a simple cosine at the pure browser end, injects Demo into quantitative and context dynamics.",
  "在自动化质量评测中，LLM Judge 的打分标准就是一种微缩版的 Constitutional AI。": "In the automated quality assessment, the LLM Judge rating criterion is a micro-contuital AI.",
  "在至少 50 组样例上自动化比对输出，确保无意外负向漂移。": "Automatically match output to ensure no unexpected negative drift in at least 50 sample groups.",
  "在设计 Agent 产品时，必须在 UI 上向用户暴露 Thought 与 Observation 的过程状态，否则黑盒等待 30 秒会带来极差的用户体验。": "When designing the Agent product, it is necessary to expose to users on UI the process state of Thorought and Observation, otherwise the black box waits 30 seconds for a very poor user experience.",
