  "在资源列表旁查看说明，关闭后保留列表滚动位置。": "View the description next to the resource list and keep the list scroll position after closing.",
  "在页面变慢之前，为资源和体验设一条明确边界。": "Establish a clear boundary for resources and experience before the page slows down.",
  "在项目规则中写清测试命令与受保护范围，让 AI 按一致方式工作。": "Write the test order and the protected range in the project rules so that AI works in a consistent manner.",
