  "大型改动前先检查状态、运行测试并建立清晰提交，形成可恢复点。": "Major changes are preceded by a state check, a run test and a clear submission to form a recoverable point.",
  "大模型与外部上下文、本地资源、执行工具解耦的最新通用协议规范，未来全行业 Agent 的基础设施。": "The most recent generic protocol norm for large models to be reconciled with external context, local resources, implementation tools, future industry-wide Agent infrastructure.",
  "大模型在预训练后权重固定，无法感知私有数据或最新信息；若直接微调 (Fine-tuning) 成本高昂且容易遗忘旧知识。": "Large models have fixed weights after pre-training and do not sense private data or up-to-date information; if fine-tuning is direct, it is costly and easy to forget old knowledge.",
  "大模型打分容易受回复长度、语气礼貌程度干扰，出现“长回复高分”或“自相矛盾打分”。通过字段级拆分与强制结构化理由先行（CoT + JSON Schema）彻底解决。": "Large models are susceptible to response lengths and politeness, with a “long return high” or “controversial” rating. The rationale for the division and forced structuralization of the fields (CoT + JSON Schema) is thoroughly resolved.",
  "大模型按 5 个维度输出结构化评估报告。": "The large model structured the assessment report by 5 dimensions.",
  "大量使用 !important 掩盖层叠问题": "Extensive use of the!important mask",
  "天气 API 接收城市代码，返回温度、天气状态和更新时间。": "Weather API receives city code, returns temperature, weather status and updates.",
  "失败信息不泄露账号是否存在": "Could not close temporary folder: %s",
  "失败包括无效输入、模型误判、请求超时和外部工具异常。应区分可重试、需补充信息和需人工介入的情况。": "Failures include invalid input, miscalculation of models, requests for overtime and anomalies in external tools. A distinction should be made between re-testable situations requiring additional information and manual intervention.",
  "失败后保留输入并给出可执行的恢复方式": "Keep input and give an enforceable recovery after failure",
  "失败后只重跑而不理解原因": "When you fail, you run again without understanding why.",
  "失败矩阵：触发条件、用户提示、重试规则、降级方案与日志。": "Failure matrix: trigger conditions, user alerts, retry rules, downgrade schemes and logs.",
