  "契约测试": "Contract Testing",
  "好架构不是消除全部不确定性，而是为不确定性划定清晰的安全边界。规则引擎负责格式与状态机，LLM Judge 负责同理心与语义。": "A good structure does not remove all uncertainties, but rather establishes clear security boundaries for them. The rule engine is responsible for formatting and status machines, and LLM Judge is responsible for synonyms and semantics.",
  "好的提交最重要的特征是什么？": "What are the most important features of a good submission?",
  "如何将确定性逻辑与主观语义评测解耦并建立自动化流水线": "How to reconcile definitive logic with subjective semantics and create automated flow lines",
  "如果加提醒你会每天用吗？": "Would you use it every day if you warned?",
  "如果状态散落在元素文字和 CSS 类名里，页面很容易互相矛盾。把状态集中表达，渲染结果才可预测。": "If the status is scattered in the element text and CSS class name, the page is easily contradictory. Focus on the state, and the results are predictable.",
  "如果直接从页面输入框设计数据库，相同概念会被重复保存，未来统计、权限和迁移都会变得困难。": "If the database is designed directly from the page box, the same concept will be duplicated and future statistics, privileges and migrations will be difficult.",
