  "学习站 MVP 先提供术语搜索、详情、收藏和进度，不急着加入社交排行榜。": "The study site MVP first provides terminological searches, details, collections and progress without rushing to join the social agenda.",
  "学习笔记用井号标记章节，用链接保存参考来源；发布时再渲染成网页。": "Learning notes are marked with well-numbered sections, with links to save reference sources; web pages are rendered when published.",
  "学习者不知道下一步学什么，常在完成第一课后离开": "Learners don't know what to learn. They leave after class one.",
  "学习资料和项目经验分散在不同地方，新增内容时又容易被页面调整打断。既希望自己能回看关键记录，也希望读者能理解项目为什么做、怎样推进。": "Learning materials and project experience are scattered in different locations and new content is easily interrupted by page adjustments. It is hoped that it will be able to look back at the key records, and that the reader will understand why and how the project will proceed.",
  "它不是 Git 本身的命令，而是团队在合并前建立共同理解和质量门槛的工作界面。": "It is not an order of Git itself, but a working interface of the team to establish a common understanding and quality threshold prior to consolidation.",
  "它不是粗糙半成品，而是主动减少次要范围，把时间用在最需要验证的用户价值上。": "It is not a rough, semi-finished product, but a proactive reduction of the secondary range, with time spent on the user values most in need of validation.",
  "它便于人阅读和程序解析，但只负责表示数据，不会自动验证字段含义或执行函数。": "It is easy for people to read and program to interpret, but is only responsible for data and does not automatically validate field meanings or perform functions.",
  "它允许隔离实验和并行协作，但长期不合并的大分支会积累冲突。": "It allows isolation experiments and parallel collaboration, but long-term non-integrated large branches accumulate conflict.",
  "它减少仓库噪声并避免误提交秘密，但对已经被 Git 跟踪的文件不会自动取消跟踪。": "It reduces the amount of noise in the warehouse and avoids the false submission of secrets, but it does not automatically cancel a document already tracked by Git.",
  "它可以减少模型只依赖训练记忆的问题，但检索错了、资料过期或引用不相关时，回答仍会错误。": "It can reduce the problem of the model relying solely on training memory, but the answer is still incorrect when the search is wrong, the information is outdated or the reference is irrelevant.",
  "它和 IA、Sitemap 有什么区别？": "What's the difference between it and the IA, the Sitemap?",
  "它帮助团队讨论为什么做，但不能替代详细验收标准、交互边界和研究证据。": "It helps the team to discuss why, but is not a substitute for detailed acceptance criteria, cross-borders and research evidence.",
  "它描述了用户、阻碍和可观察影响，没有提前锁死解决方式。": "It describes user, obstruction and observable effects, without early locking to death.",
  "它给出了环境、可观察结果和明确边界，可以真实检查。": "It gives an environment, visible results and clear boundaries, which can be checked for real.",
  "它要求讲述最近的真实经历，能得到行为、障碍和替代方案证据。": "It requires a description of recent real experiences and evidence of behaviour, obstacles and alternatives.",
  "它适合主题、草稿和离线状态，但不是跨用户共享数据库，清理浏览器数据后也可能消失。": "It is suitable for themes, drafts and offline states, but it is not shared across users, and may disappear after cleaning up browser data.",
