  "将大模型的“内部思维推理 (Thought)”与“外部工具调用行动 (Action)”以及“环境反馈观察 (Observation)”交替编排，让 Agent 具备解决复杂多步任务的能力。": "The large model's “Thought” has been organized in turn with “Action for External Tools” and “Environmental Feedback” to equip Agent with the ability to solve complex multi-step tasks.",
  "将头像简化成小尺寸仍清晰的图形，避免直接缩小整幅插画。": "Simplify the head image into small-scale graphics that are still clear and avoid reducing the entire illustration directly.",
  "将密钥放在服务端": "Place key on service",
  "将岗位助手整理成案例时，展示脱敏样例和失败分析；没有真实用户数据就说明验证仍在进行。": "When a job assistant is organized into a case, a dissensitization sample and a failure analysis are displayed; without real user data, certification is still ongoing.",
  "将抽象枯燥的技术标准转化为场景化、步骤清晰、带可交互运行窗口的学习体验典范。": "Translating abstract and dry technical standards into a model of learning experience with landscapes, clear steps and interactive windows.",
  "将旧资料入口接入资源目录，补齐从详情返回时的筛选恢复。": "The old data entry access directory is completed and the filter is restored upon return from details.",
  "将本地文件传送到应用或服务器的过程和交互入口。": "Processes and interactive portals for transmitting local files to applications or servers.",
  "将语义评测项拆分为原子维度": "Split semantic assessments into atomic dimensions",
  "将较大集合分成有限大小的页面浏览。": "Splits the larger group into pages of limited size.",
  "将页面主要内容分成并列两部分的结构。": "Splits the main contents of the page into a two-part structure.",
  "将预训练模型的“参数化记忆”与外部文档索引的“非参数化检索”结合，低成本解决大模型知识滞后与幻觉问题。": "Combining the “parametrical memory” of the pre-trained model with the “non-parametric retrieval” of the index to the external document, low-cost solutions to the problem of knowledge lags and hallucinations in large models.",
  "小屏需要重新组织导航形态，同时保持主要入口可达。": "The screen needs to be reorganised in navigational mode while keeping the main entrance accessible.",
  "小工具与复用方法": "Small tools and reuse methods",
  "小程序前端交互画布 + 异步任务状态机轮询 + Docker 云托管 Node.js 渲染集群 + 图像大模型 API + CDN 缓存加速。": "The applet front-end interactive canvas + walker query + Docker cloud hosting Node.js render cluster + large image model API + CDN cache acceleration.",
  "小程序月活": "Minor programme monthly activities",
  "小程序月活突破 10,000+，图像生成成功率达到 99.6%，平均端到端出图耗时降低 45%。": "Small program monthly life break 10,000+ with a success rate of 99.6% for image generation and a 45% reduction in average end-to-end figure time.",
  "小范围上线并准备回退": "launch",
  "小范围上线并准备回退 →": "We're on line and ready to retreat.",
  "尚未记录": "Not recorded",
  "尝试新布局失败时，先保留有效内容修改，再只恢复对应样式。": "When you try a new layout fails, save the valid content changes and restore the corresponding style.",
  "就像人类在排查 Bug：先思考“为什么报错”（Thought），然后执行一条搜索或命令（Action），看到终端输出或网页内容（Observation），再根据新信息思考下一步。": "Just like humans are checking Bug: think about \"Why Wrong\" and then do a search or command, see terminal output or web content, and think about the next step based on new information.",
  "层叠、优先级与声明顺序共同决定最终生效的 CSS。": "CSS, which is determined by stacking, priority and order of declaration.",
