  "展示任务进行状态的动画时提供减少动态效果的兼容处理。": "Displays the animation of the mission to provide compatible treatment that reduces the dynamic effects.",
  "展示已发布知识数量时从数据计算，并解释统计范围。": "The amount of published knowledge is calculated from data and the statistical scope is explained.",
  "展示有顺序的流程阶段以及当前所在阶段。": "Demonstrate the sequenced process phase and current phase.",
