  "展示访谈结论时区分原话、归纳和自己的假设。": "The findings of the interviews were presented in a way that distinguished the original language, summarized and presented its own assumptions.",
  "属性名和字符串使用双引号": "Double quote for attribute names and strings",
  "属性在两个状态之间按时间变化的过程。": "The process by which the attribute changes over time between two states.",
  "岗位分析任务记录状态和错误类型，日志避免保存完整简历或密钥，结果访问需校验所属用户。": "Job-analysing job record status and type of error. Logs do not save complete resumes or keys.",
  "岗位分析用上传简历、粘贴 JD、证据对照表和可编辑结论完成流程，比要求用户连续聊天更容易核查。": "Job analysis completes the process by uploading resumes, pasting JDs, evidence checklists and editable conclusions, which is easier to verify than requiring users to talk continuously.",
  "岗位助手可观察完成一次有效对照的比例、用户修正量和耗时。不能把生成次数直接当作帮助求职成功。": "The job assistant can observe the ratio of completion of an effective comparison, the number of user corrections and the time spent. The number of times generated cannot be directly considered as helping to find a successful job.",
  "岗位助手第一版先支持一次 JD 对照与人工修改，暂不加入社区、订阅推荐或自动投递。": "The first version of the job assistant supports a JD comparison and manual modification and is suspended from the community, subscription or automatic delivery.",
  "岗位筛选先用地点和薪资规则排除明显不符项，再判断是否需要模型解释复杂的技能要求。": "Post screening rules exclude obvious discrepancies before determining whether a model is needed to explain complex skill requirements.",
