  "强化了“确定性问题用规则，非确定性语义用模型”的设计原则，奠定了评测系统的分层思想。": "The design principles of “rules for certainty, models for non-sensual semantics” were reinforced, laying down the stratification of assessment systems.",
  "强调功能、几何形与构成关系的设计传统。": "The design tradition emphasizes functional, geometric and constitutive relationships.",
  "强调浮层与底层的关系，同时适配本项目的品牌色。": "Emphasis is placed on the relationship between the layer and the bottom, while adapting to the brand of the project.",
  "强调网格、对齐、非衬线字体和客观信息组织的排版传统。": "Emphasis is placed on the layout traditions of grids, alignment, non-linear fonts and objective information organizations.",
  "当 LLM 输出不稳定、经常忽略某些负向约束、或者在边界情况下格式崩溃时使用。": "LLM output is used when it is unstable, often ignores certain negative constraints, or when format collapses in border situations.",
  "当下游处理能力不足时，反向限制上游工作输入的机制。": "Mechanisms to reverse upstream work input when downstream processing capacity is insufficient.",
  "当你的 AI Agent 或 Prompt 进入多轮对话、调用工具或处理高可靠性业务，需要建立稳定、可回归的自动化评测质量保障时。": "When your AI Agent or Prompt enters multiple rounds of dialogue, calls tools or handles high-reliability operations, you need to establish stable, reversible automated assessment quality assurance.",
  "当内容需要横纵同时对齐时，Grid 比嵌套多层 Flexbox 更能直接表达布局关系。": "When content needs to be aligned across and across, Grid can express layout relations more directly than embedded layers of Flexbox.",
  "当列表或结果没有数据时给出的说明和下一步。": "A description and next steps when the list or result does not contain data.",
  "当前可以做什么": "What can we do now?",
  "当前已有双玩法入口、编辑、手写草稿、历史记录和预览保存相关代码，最新定向成图链路已取得成功记录，可以开始人工真机功能测试；默认服务未切换，失败日志分支仍需检查。小程序尚未发布，不能作为稳定可用产品对外提供体验。": "There are now double-playing accesses, edits, handwritten drafts, historical records and previews to save the relevant codes, the latest orientations are recorded successfully, allowing the performance testing of artificial machines to begin; the default service has not been switched and the failure log branch still needs to be checked. Minor procedures have not yet been published and cannot provide external experience as a stable available product.",
  "当前所在位置清楚": "Current position clear.",
