  "当前本地预览开关已启用；同日后续定向成图测试已取得成功记录，完整设备覆盖仍待验收。": "The current local preview switch has been activated; the subsequent orientation test on the same date has been successfully documented and complete equipment coverage is still pending acceptance.",
  "当前状态：": "Current status:",
  "当前能力": "Current capacity",
  "当相同模式散落在多个页面时，文案、状态和交互很容易漂移。合理组件化能让一次修改覆盖所有正确位置。": "When the same pattern is scattered over multiple pages, the text, state and interaction can easily drift. Rational modularization allows a change to cover all correct locations.",
  "影响可以观察": "Impact can be observed.",
  "影响应能被观察或验证": "Impact should be observed or validated",
  "彻底改变了企业级 AI 应用的落地范式，使私有数据与开源大模型的高效安全结合成为标准实践。": "A radical change has been made in the industry-level AI application ' s landing paradigm to make the efficient and safe integration of private data with open source large models standard practice.",
  "彻底放弃 RNN 循环时序与卷积，仅凭 Self-Attention 机制实现高并行、长距离依赖建模，奠定了现代所有大模型的基础。": "The complete abandonment of the RNN cycle time series and volume, with the Self-Attention mechanism alone to achieve high parallel, long-range reliance modelling, lays the foundation for all modern large models.",
