  "某退款 Agent 测试集包含 95 个常规查询和 5 个越权攻击用例。模型对所有用例全部放行，Accuracy 为 95%，但对高危攻击的 Recall 为 0%。引入多维召回矩阵后，设立高危风险 Recall ≥ 99.5% 门禁，成功在发布前拦截全部风险。": "An Agent test set contains 95 routine queries and 5 examples of ultra vires attacks. The model was released for all examples, 95 per cent for Accuracy, but 0 per cent for Recall for high-risk attacks. The introduction of a multi-dimensional recall matrix has resulted in the establishment of a high-risk recall ≥ 99.5 per cent lockdown, which successfully intercepts all risks before they are released.",
