  "正确的结构能同时帮助浏览器、搜索引擎、屏幕阅读器和未来维护代码的人理解页面。样式可以变化，内容的身份不应该随之丢失。": "The right structure helps both browsers, search engines, screen readers and future code maintenance users to understand the page. The style can change and the identity of the content should not be lost.",
  "正确路由让前进、后退、刷新和分享链接都可用；页内锚点与应用路由还需要避免冲突。": "The correct route is available for moving forward, backsliding, refreshing and sharing links; there is also a need to avoid conflict between the anchor and the application route.",
  "此前消息与工具结果的记录，可作为后续请求的上下文。": "Previous information and documentation of the results of the tool may serve as the context for follow-up requests.",
  "此页依据仓库说明整理，未执行安装或跨设备同步测试。": "This page is organized on the basis of the warehouse description and does not perform installation or equipment synchronization tests.",
  "步骤条": "Steps",
  "每一步只要求必要信息": "Every step requires only the necessary information.",
  "每个 LLM Judge Prompt 仅负责一个具体维度的判定（如“是否正确识别了用户潜在拒绝情绪”），避免多任务干扰。": "Each LLM Judge Prompt is responsible for the determination of a specific dimension (e.g. “whether or not to correctly identify a potential user's rejection), avoiding multitasking.",
  "每个主要页面应有稳定地址": "Each major page should have a stable address",
  "每个状态变化都应有明确触发原因": "Each state change should have a clear trigger.",
  "每个评测维度只回答 Yes/No，Prompt 输出强制采用 JSON Schema：{ evidence: string, reasoning: string, passed: boolean }。": "Yes/ No, Prompt output only enforces the use of JSON Schema:",
