  "每条记录都连接到对应项目，完整背景与过程留在项目详情中。": "Each record is connected to the corresponding item and the complete background and process is left in the project details.",
  "每次发布前自动化运行 Diff 回归": "Automatically run Diff returns before each release",
  "每次提交触发测试，尽早暴露与主分支的不兼容。": "Each time a trigger test is submitted, the incompatibility with the main branch is revealed as early as possible.",
  "每次操作都应该有明确结果，错误发生时用户能继续处理。": "Each operation should have clear results and the user can continue to process the error when it occurs.",
