  "没有 Transformer 就没有今天的 GPT、Claude 和 Gemini。它将自然语言处理从串行工程带入了大规模 GPU 并行与 Scaling Law 时代。": "No Transformer has no GPT, Claude and Gemini today. It brought natural language processing from serial engineering to a large GPU parallel to the Scaling Law era.",
