  "浏览器事件": "Browser Event",
  "浏览器事件是用户或系统发生动作时产生的通知，例如 click、input、submit 和 keydown。代码通过监听器响应这些事件。": "Browser events are notifications generated by actions of the user or system, such as click, input, submit and keydown. The code responds to these events through a listening device.",
  "浏览器先读取 HTML 建立页面骨架，CSS 再负责外观，JavaScript 再负责变化和行为。结构写错会影响可访问性、搜索和交互。": "Browser first reads HTML to create a page skeleton, then CSS to look, JavaScript to change and behave. Structural errors affect accessibility, search and interaction.",
  "浏览器刷新后仍存在、跨设备共享并需要权限控制的数据，通常要进入服务端持久化存储。": "The browser refreshs data that are still available, shared across the device and requires permission control, and usually enters a service-end permanent storage.",
  "浏览器存储": "Browser Storage",
  "浏览器存储是在用户设备上保存数据的机制，常见有 localStorage、sessionStorage 和 IndexedDB。": "Browser storage is the mechanism by which data are saved on user devices, most commonly localStorage, sessionStorage, and IndexDB.",
  "浏览器存储通常只属于当前浏览器环境，跨设备同步需要服务端数据。": "Browser storage usually belongs only to the current browser environment, and synchronisation across devices requires service-end data.",
